INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Erhalte ich bei der Aufteilung von 2001:db8::/48 in /64 genau 65.536 Subnetze?', 2, '[{"text": "Ja", "correct": true, "because": "2^(64-48) = 2^16"}, {"text": "Nein", "correct": false, "because": "Formel passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetzadressen entstehen aus 2001:db8::/56 in /64?', 3, '[{"text": "256", "correct": true, "because": "2^(64-56) = 2^8"}, {"text": "64", "correct": false, "because": "Zu niedrig"}, {"text": "1024", "correct": false, "because": "Zu hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzadresse folgt auf 2001:db8:1::/64?', 4, '[{"text": "2001:db8:2::/64", "correct": true, "because": "Hexadezimal inkrementiert"}, {"text": "2001:db8:1:1::/64", "correct": false, "because": "Innerhalb desselben"}, {"text": "2001:db9::/64", "correct": false, "because": "Falscher Block"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2001:db8::/48 ergibt 65.536 /64-Subnetze. b) Erste Adresse ist 2001:db8::/64.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 2^16, b) Startadresse"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei den Ergebnissen einer /48 zu /64 Aufteilung?', 5, '[{"text": "Einzelne Hostadressen", "correct": true, "because": "Nur Subnetze zählen"}, {"text": "Subnetzanzahl", "correct": false, "because": "Kern des Ergebnisses"}, {"text": "Subnetzadressen", "correct": false, "because": "Hauptfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die letzte Subnetzadresse von 2001:db8::/48 in /64 2001:db8:ffff::/64 ist?', 2, '[{"text": "Ja", "correct": true, "because": "FFFF ist max. bei 16 Bits"}, {"text": "Nein", "correct": false, "because": "Hexadezimal korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anzahl Subnetze ergibt 2001:db8::/60 in /64?', 3, '[{"text": "16", "correct": true, "because": "2^(64-60) = 2^4"}, {"text": "8", "correct": false, "because": "Zu niedrig"}, {"text": "32", "correct": false, "because": "Zu hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzadressen entstehen zuerst aus 2001:db8::/48 in /64?', 5, '[{"text": "2001:db8::/64", "correct": true, "because": "Erste Adresse"}, {"text": "2001:db8:1::/64", "correct": true, "because": "Zweite Adresse"}, {"text": "2001:db8:2::/64", "correct": false, "because": "Dritte Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 2001:db8::/48 in /64 ergibt 2^16 Subnetze. b) Letzte Adresse ist 2001:db8::ffff:/64. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, korrekt 2001:db8:ffff::/64"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Ergebnisse einer Aufteilung?', 4, '[{"text": "Subnetzanzahl", "correct": false, "because": "Kern des Ergebnisses"}, {"text": "Subnetzadressen", "correct": false, "because": "Hauptfokus"}, {"text": "Übertragungsrate", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 2001:db8:10::/64 die 17. Subnetzadresse von 2001:db8::/48?', 2, '[{"text": "Ja", "correct": true, "because": "Hex 10 = 16 + 1"}, {"text": "Nein", "correct": false, "because": "Hexadezimal korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse erwartest du bei 2001:db8::/48 in /64?', 4, '[{"text": "65.536 Subnetze", "correct": true, "because": "2^16"}, {"text": "Start: 2001:db8::/64", "correct": true, "because": "Erste Adresse"}, {"text": "Ende: 2001:db8::ffff:/64", "correct": false, "because": "Korrekt 2001:db8:ffff::/64"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 2001:db8::/56 in /64 nur 128 Subnetze ergibt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "2^8 = 256"}, {"text": "Ja", "correct": false, "because": "Falsche Anzahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei den Ergebnissen einer Aufteilung?', 3, '[{"text": "Subnetzanzahl", "correct": true, "because": "Hauptziel der Aufteilung"}, {"text": "Einzelne IPs", "correct": false, "because": "Sekundär"}, {"text": "Kürzungsregeln", "correct": false, "because": "Darstellungssache"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2001:db8::/48 hat 65.536 /64-Subnetze. b) Zweite Adresse ist 2001:db8:2::/64.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, zweite ist 2001:db8:1::/64"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten die Ergebnisse einer /48 zu /64 Aufteilung?', 5, '[{"text": "Viele Subnetze", "correct": true, "because": "65.536 Möglichkeiten"}, {"text": "Klar definierte Adressen", "correct": true, "because": "Hexadezimalzählung"}, {"text": "Wenige Subnetze", "correct": false, "because": "Große Anzahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei den Ergebnissen unwichtig?', 3, '[{"text": "Subnetzanzahl", "correct": false, "because": "Kern des Ergebnisses"}, {"text": "Subnetzadressen", "correct": false, "because": "Hauptfokus"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 2001:db8:ffff::/64 die letzte Adresse von 2001:db8::/48?', 2, '[{"text": "Ja", "correct": true, "because": "Max. bei 16 Bits"}, {"text": "Nein", "correct": false, "because": "Hexadezimal korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2001:db8:1f::/64 die 32. Subnetzadresse von 2001:db8::/48 ist?', 3, '[{"text": "Ja", "correct": true, "because": "Hex 1f = 31 + 1"}, {"text": "Nein", "correct": false, "because": "Hexadezimal passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzadresse ist die 5. bei 2001:db8::/48 in /64?', 4, '[{"text": "2001:db8:4::/64", "correct": true, "because": "Hex 0,1,2,3,4"}, {"text": "2001:db8:5::/64", "correct": false, "because": "6. Adresse"}, {"text": "2001:db8:3::/64", "correct": false, "because": "4. Adresse"}]');
